      "module_name": "Mathlib.Data.Finsupp.SMul",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_3} {R : Type u_6} [inst : Semiring R] [IsDomain R] [inst_2 : AddCommMonoid M]\n  [inst_3 : Module R M] [Module.IsTorsionFree R M] {b : R}, b ≠ 0 → ∀ {g : α →₀ M}, (b • g).support = g.support"
    },
    {
      "name": "Function.support_const_smul_of_ne_zero",
      "module_name": "Mathlib.Algebra.Module.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {R : Type u_2} {M : Type u_3} [inst : Semiring R] [IsDomain R] [inst_2 : AddCommMonoid M]\n  [inst_3 : Module R M] [Module.IsTorsionFree R M] (c : R) (g : α → M),\n  c ≠ 0 → Function.support (c • g) = Function.support g"
    },
    {
      "name": "MvPolynomial.support_smul_eq",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {S : Type u_2} [inst_1 : Semiring S] [IsDomain S]\n  [inst_3 : Module S R] [Module.IsTorsionFree S R] {a : S},\n  a ≠ 0 → ∀ (p : MvPolynomial σ R), (a • p).support = p.support"
    },
    {
      "name": "Finsupp.support_smul",
      "module_name": "Mathlib.Data.Finsupp.SMulWithZero",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_5} {R : Type u_11} [inst : Zero M] [inst_1 : SMulZeroClass R M] {b : R} {g : α →₀ M},\n  (b • g).support ⊆ g.support"
    },
    {
      "name": "Function.support_smul",
      "module_name": "Mathlib.Algebra.Module.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {R : Type u_2} {M : Type u_3} [inst : Semiring R] [IsDomain R] [inst_2 : AddCommMonoid M]\n  [inst_3 : Module R M] [Module.IsTorsionFree R M] (f : α → R) (g : α → M),\n  Function.support (f • g) = Function.support f ∩ Function.support g"
    }
  ]
